with scored as (select *, row_number() over (partition by plan order by end_date, id) as row_seq, avg(monthly_fee) over (partition by status, plan order by start_date, id rows between 6 preceding and 1 preceding) as monthly_fee_avg_6_prior, round(monthly_fee / sum(monthly_fee) over (partition by plan), 4) as monthly_fee_share from subscriptions) select id, plan, start_date, end_date, status, monthly_fee_avg_6_prior, monthly_fee_share from scored
